@Test public void testPseudoHas() {
    Document doc = Jsoup.parse("<div id=0><p><span>Hello</span></p></div> <div id=1><span class=foo>There</span></div> <div id=2><p>Not</p></div>");

    Elements divs1 = doc.select("div:has(span)");
    assertEquals(2, divs1.size());
    assertEquals("0", divs1.get(0).id());
    assertEquals("1", divs1.get(1).id());

    Elements divs2 = doc.select("div:has([class])");
    assertEquals(1, divs2.size());
    assertEquals("1", divs2.get(0).id());

    Elements divs3 = doc.select("div:has(span, p)");
    assertEquals(3, divs3.size());
    assertEquals("0", divs3.get(0).id());
    assertEquals("1", divs3.get(1).id());
    assertEquals("2", divs3.get(2).id());

    Elements els1 = doc.body().select(":has(p)");
    assertEquals(3, els1.size()); // body, div, div
    assertEquals("body", els1.first().tagName());
    assertEquals("0", els1.get(1).id());
    assertEquals("2", els1.get(2).id());

    Elements els2 = doc.body().select(":has(> span)");
    assertEquals(2,els2.size()); // p, div
    assertEquals("p",els2.first().tagName());
    assertEquals("1", els2.get(1).id());
}

@Test public void testNestedHas() {
    Document doc = Jsoup.parse("<div><p><span>One</span></p></div> <div><p>Two</p></div>");
    Elements divs = doc.select("div:has(p:has(span))");
    assertEquals(1, divs.size());
    assertEquals("One", divs.first().text());

    // test matches in has
    divs = doc.select("div:has(p:matches((?i)two))");
    assertEquals(1, divs.size());
    assertEquals("div", divs.first().tagName());
    assertEquals("Two", divs.first().text());

    // test contains in has
    divs = doc.select("div:has(p:contains(two))");
    assertEquals(1, divs.size());
    assertEquals("div", divs.first().tagName());
    assertEquals("Two", divs.first().text());
}

@Test public void testHasSibling() {
    // https://github.com/jhy/jsoup/issues/2137
    Document doc = Jsoup.parse("<h1 id=1>One</h1> <h2>Two</h2> <h1>Three</h1>");
    Elements els = doc.select("h1:has(+h2)");
    assertSelectedIds(els, "1");

    els = doc.select("h1:has(~h1)");
    assertSelectedIds(els, "1");

    // nested with sibling
    doc = Jsoup.parse("<div id=1><p><i>One</i><i>Two</p><p><i>Three</p></div> <div><p><i>Four</div>");
    els = doc.select("div:has(p:has(i:has(~i)))");
    assertSelectedIds(els, "1");
}

@Test public void testHasRelativeScope() {
    // relative selectors in :has are anchored to the tested element; :scope is the explicit form of that anchor
    Document doc = Jsoup.parse(
        "<article id=a><h1></h1><h2></h2><p><b></b><i></i></p></article>" +
        "<article id=z><h1></h1><p></p><b></b><i></i></article>");

    assertSelectedIds(doc.select("article:has(> h1 + h2)"), "a");
    assertSelectedIds(doc.select("article:has(> b + i)"), "z");
    assertSelectedIds(doc.select("article:has(p:has(> b + i))"), "a");
    assertSelectedIds(doc.select("article:has(:scope > p > b + i)"), "a");
    assertSelectedIds(doc.select("article:has(+ article)"), "a");

    // css escapes in pseudo-class names are equivalent to the unescaped names
    assertSelectedIds(doc.select("article:h\\61 s(> h1 + h2)"), "a");
    assertSelectedIds(doc.select("article:h\\61 s(:sc\\6f pe > p > b + i)"), "a");

    // explicit :scope is equivalent to the implicit anchor of a leading combinator
    assertSelectedIds(doc.select("article:has(:scope > h1 + h2)"), "a");
    assertSelectedIds(doc.select("article:has(:scope + article)"), "a");
}

@Test public void testHasSiblingChain() {
    // a branch starting with + or ~ is anchored to the element's following siblings, and the chain continues from there
    Document doc = Jsoup.parse("<article id=a></article><article id=b><p></p></article><article id=c></article>");
    assertSelectedIds(doc.select("article:has(+ article > p)"), "a");
    assertSelectedIds(doc.select("article:has(+ article p)"), "a");
    assertSelectedIds(doc.select("article:has(~ article)"), "a", "b");

    // mixed branches: each branch is tested against its own candidate set
    doc = Jsoup.parse("<article id=a><h1></h1></article><article id=b></article><article id=c></article>");
    assertSelectedIds(doc.select("article:has(> h1, + article)"), "a", "b");
}

@Test public void testHasDoesNotCrossSubtree() {
    // a branch without a leading + or ~ combinator must not match siblings outside the element's subtree
    Document doc = Jsoup.parse("<h1></h1><article id=a></article><h2></h2>");
    assertEquals(0, doc.select("article:has(h1 ~ h2)").size());
    assertEquals(0, doc.select("article:has(h1 + h2)").size());

    // ... but does match when the chain is contained within the subtree
    doc = Jsoup.parse("<article id=a><h1></h1><h2></h2></article><article id=b><h1></h1></article>");
    assertSelectedIds(doc.select("article:has(h1 ~ h2)"), "a");
}

@Test public void testHasSiblingLeafChain() {
    // a leading ~ walks the following node siblings, so text / comment leaves are valid matches and can be skipped
    Document doc = Jsoup.parse("<article id=a></article><p id=gap></p><!--c--><b></b><i></i>");
    assertSelectedIds(doc.select("article:has(~ ::comment)"), "a");
    assertSelectedIds(doc.select("article:has(:scope ~ ::comment)"), "a");

    // a leading + compares the immediate following node, so the intervening <p> blocks the comment
    assertEquals(0, doc.select("article:has(+ ::comment)").size());
    assertEquals(0, doc.select("article:has(:scope + ::comment)").size());

    // ~ can skip over a gap element to a text leaf; + cannot
    doc = Jsoup.parse("<article id=a></article><p id=gap></p>txt");
    assertSelectedIds(doc.select("article:has(~ ::text)"), "a");
    assertEquals(0, doc.select("article:has(+ ::text)").size());

    // without a gap, the comment is the immediate following node
    doc = Jsoup.parse("<article id=a></article><!--c--><b></b>");
    assertSelectedIds(doc.select("article:has(+ ::comment)"), "a");
}

@Test public void testHasSiblingLeafChainSteps() {
    // once a leaf selector appears in a sibling chain, every + step compares the full node sequence one by one
    Document doc = Jsoup.parse("<article id=a></article><!--c--><b></b>txt<i></i>");
    assertSelectedIds(doc.select("article:has(+ ::comment + b)"), "a");
    assertSelectedIds(doc.select("article:has(+ b + i)"), "a"); // pure element chain ignores the intervening text

    // but this mixed chain requires comment -> b -> i consecutively, with the text between b and i blocking it
    assertEquals(0, doc.select("article:has(+ ::comment + b + i)").size());

    // pure element chains keep ignoring leaves between elements
    doc = Jsoup.parse("<article id=a></article><!--x--><b></b>txt<i></i>");
    assertSelectedIds(doc.select("article:has(+ b + i)"), "a");
}

@Test public void testHasLeafChainInsideSubtree() {
    // leaf-chain adjacency applies to sibling steps inside the scope's descendants as well
    Document doc = Jsoup.parse("<article id=a><h1></h1><!--c--></article>");
    assertSelectedIds(doc.select("article:has(h1 + ::comment)"), "a");
    assertSelectedIds(doc.select("article:has(h1 ~ ::comment)"), "a");

    // intervening text blocks + but not ~
    doc = Jsoup.parse("<article id=a><h1></h1>txt<!--c--></article>");
    assertEquals(0, doc.select("article:has(h1 + ::comment)").size());
    assertSelectedIds(doc.select("article:has(h1 ~ ::comment)"), "a");
}

@Test public void testHasContainerAndNestedSelfAnchored() {
    // :is() and :not() establish their own anchor; a sibling combinator inside must not borrow the outer scope's
    // following siblings
    Document doc = Jsoup.parse("<article id=a></article><p></p>");
    assertEquals(0, doc.select("article:has(:is(+ p))").size());
    assertEquals(0, doc.select("article:has(:not(+ p))").size());

    // a compounded :scope still anchors a leading combinator
    assertSelectedIds(doc.select("article:has(:scope:not(.x) + p)"), "a");

    // a nested :has() re-anchors to its own tested element; its + never reaches the outer element's siblings
    doc = Jsoup.parse("<article id=a><div></div><p></p></article>");
    assertSelectedIds(doc.select("article:has(div:has(+ p))"), "a");
    doc = Jsoup.parse("<article id=a></article><div><p></p></div>");
    assertEquals(0, doc.select("article:has(div:has(+ p))").size());
}

@Test public void testHasLeafChainBranchesIndependent() {
    // each comma-separated branch keeps its own descendant / sibling set and element / node mode
    Document doc = Jsoup.parse("<article id=a></article><p></p><!--c-->");
    assertSelectedIds(doc.select("article:has(+ p, ~ ::comment)"), "a");
    assertSelectedIds(doc.select("article:has(+ ::comment, + p)"), "a");

