package org.jsoup.select;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class ScratchHasBranchesTest {
    @Test void multiBranchesIndependent() {
        Document doc = Jsoup.parse("<div id=a><p>x</p></div><div id=b><span>y</span></div><div id=c><i>z</i></div>");
        Elements els = doc.select("div:has(p, span)");
        assertEquals(2, els.size());
        assertEquals("a", els.get(0).id());
        assertEquals("b", els.get(1).id());
    }

    @Test void multipleBranchesHitOnce() {
        Document doc = Jsoup.parse("<div id=a><p>x</p><span>y</span></div>");
        Elements els = doc.select("div:has(p, span)");
        assertEquals(1, els.size());
        assertSame(doc.getElementById("a"), els.first());
    }

    @Test void deadBranchDoesNotKillOthers() {
        Document doc = Jsoup.parse("<div id=a><p>x</p></div><div id=b></div>");
        Elements els = doc.select("div:has(section, p)");
        assertEquals(1, els.size());
        assertEquals("a", els.first().id());
    }

    @Test void emptyBranchIsNotTrue() {
        assertThrows(Selector.SelectorParseException.class, () -> Jsoup.parse("<div id=a><p></p></div>").select("div:has(p, )"));
        assertThrows(Selector.SelectorParseException.class, () -> Jsoup.parse("<div></div>").select("div:has()"));
    }

    @Test void danglingCombinatorFailsWholeQuery() {
        assertThrows(Selector.SelectorParseException.class, () -> Jsoup.parse("<div><p></p></div>").select("div:has(p, >)"));
        assertThrows(Selector.SelectorParseException.class, () -> Jsoup.parse("<div><p></p></div>").select("div:has(p >)"));
        assertThrows(Selector.SelectorParseException.class, () -> Jsoup.parse("<div><p></p></div>").select("div:has(p, "));
        assertThrows(Selector.SelectorParseException.class, () -> Jsoup.parse("<div><p></p></div>").select("div:has(p, :not()"));
    }

    @Test void docUsableAfterParseError() {
        Document doc = Jsoup.parse("<div id=a><p>x</p></div>");
        assertThrows(Selector.SelectorParseException.class, () -> doc.select("div:has(p, >)"));
        Elements els = doc.select("div:has(p)");
        assertEquals(1, els.size());
        assertEquals("<div id=\"a\">\n <p>x</p>\n</div>", els.outerHtml());
    }

    @Test void wildcardNotNested() {
        Document doc = Jsoup.parse("<div id=a><p><b></b></p></div><div id=b>txt</div>");
        Elements els = doc.select("div:has(*)");
        assertEquals(1, els.size());
        assertEquals("a", els.first().id());
    }

    @Test void notInBranches() {
        Document doc = Jsoup.parse("<div id=a><p class=x></p></div><div id=b><p></p></div>");
        Elements els = doc.select("div:has(p:not(.x), section)");
        assertEquals(1, els.size());
        assertEquals("b", els.first().id());
    }

    @Test void nestedHasScoped() {
        // sibling inside nested has must not see outer candidate's siblings
        Document doc = Jsoup.parse("<article id=a></article><div><p></p></div>");
        assertEquals(0, doc.select("article:has(div:has(+ p))").size());
    }

    @Test void parentAndChildDocOrder() {
        Document doc = Jsoup.parse("<div id=outer><div id=inner><p></p></div></div>");
        Elements els = doc.select("div:has(p)");
        assertEquals(2, els.size());
        assertEquals("outer", els.get(0).id());
        assertEquals("inner", els.get(1).id());
    }

    @Test void repeatedQueriesStable() {
        Document doc = Jsoup.parse("<div id=a><p></p><span></span></div>");
        String html1 = doc.html();
        Elements r1 = doc.select("div:has(p, span)");
        Elements r2 = doc.select("div:has(p, span)");
        assertEquals(r1.size(), r2.size());
        assertSame(r1.first(), r2.first());
        assertEquals(html1, doc.html());
    }

    @Test void noMutation() {
        Document doc = Jsoup.parse("<div id=a class=\"foo bar\"><p title=\"hello &amp; goodbye\">x</p></div>");
        String before = doc.html();
        doc.select("div:has(p[title])");
        assertEquals(before, doc.html());
    }

    @Test void serializeReparseEquivalent() {
        String html = "<div id=a><p>one</p></div><div id=b><span>two</span></div><div id=c><i>three</i></div>";
        Document d1 = Jsoup.parse(html);
        Elements r1 = d1.select("div:has(p, span, i)");
        Document d2 = Jsoup.parse(d1.html());
        Elements r2 = d2.select("div:has(p, span, i)");
        assertEquals(r1.outerHtml(), r2.outerHtml());
        assertEquals(3, r2.size());
    }

    @Test void escapedClassAndEntities() {
        Document doc = Jsoup.parse("<div id=a><p class=\"foo.bar\"></p></div><div id=b title=\"a&amp;b\"><span></span></div>");
        assertEquals(1, doc.select("div:has(p.foo\\.bar)").size());
        assertEquals("a", doc.select("div:has(p.foo\\.bar)").first().id());
        assertEquals(1, doc.select("div:has([title='a&b'])").size());
    }

    @Test void emptyAndNoMatch() {
        Document empty = Jsoup.parse("");
        assertTrue(empty.select("div:has(p, span)").isEmpty());
        Document doc = Jsoup.parse("<div></div>");
        assertTrue(doc.select("div:has(p, span)").isEmpty());
        // subsequent call fine
        assertTrue(doc.select("div:has(p)").isEmpty());
    }

    @Test void noDuplicateObjects() {
        Document doc = Jsoup.parse("<div id=a><p><b></b></p></div>");
        Elements els = doc.select("div:has(p, p b)");
        assertEquals(1, els.size());
