import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.select.Evaluator;
import org.jsoup.select.QueryParser;
import org.jsoup.select.Selector;
public class T4 {
  static void t(Document doc, String q) {
    try { System.out.println(q + " => " + doc.select(q).size()); }
    catch (Exception e) { System.out.println(q + " => ERR " + e.getClass().getSimpleName() + ": " + e.getMessage()); }
  }
  public static void main(String[] a) {
    Document doc = Jsoup.parse("<div id=a><p class=x></p><section></section></div><div id=b><p></p></div>");
    t(doc, "div:has(p:not(.x, .y))");
    t(doc, "div:has(:is(p, section))");
    t(doc, "div:has(:not(p))");
    t(doc, "div:has(*:not(p))");
    t(doc, "div:has(p, span, )");
    t(doc, "div:has((p)");
    t(doc, "div:has(p), )");
    t(doc, "div:has(p , span)");
    t(doc, "div:has( p , span )");
    t(doc, "div:has(>p,>span)");
    t(doc, "div:has(p,,span)");

    // compiled evaluator reused across two different docs
    Evaluator eval = QueryParser.parse("div:has(p, span)");
    Document d1 = Jsoup.parse("<div id=x><p></p></div>");
    Document d2 = Jsoup.parse("<div id=y><span></span></div><div id=z></div>");
    System.out.println("d1: " + Selector.select(eval, d1).size());
    System.out.println("d2: " + Selector.select(eval, d2).size());
    System.out.println("d1 again: " + Selector.select(eval, d1).size());

    // same selector on same doc many times
