13	/** Evaluates the relative selectors inside {@code :has()}. */
14	final class HasEvaluator extends Evaluator {
15	    private final String selector;
16	    final List<Traversal> traversals;
17	    private final boolean wantsNodes;
18	    private final int cost;
19	
20	    /** Creates an evaluator from the canonical selector text and its planned traversals. */
21	    HasEvaluator(String selector, List<Traversal> traversals) {
22	        this.selector = selector;
23	        this.traversals = Collections.unmodifiableList(new ArrayList<>(traversals));
24	        boolean wantsNodes = false;
25	        int evaluatorCost = 0;
26	        for (Traversal traversal : traversals) {
27	            wantsNodes |= traversal.evaluator.wantsNodes();
28	            evaluatorCost += traversal.evaluator.cost();
29	        }
30	        this.wantsNodes = wantsNodes;
31	        this.cost = 10 * evaluatorCost;
32	    }
33	
34	    @Override public boolean matches(Element root, Element element) {
35	        for (Traversal traversal : traversals) {
36	            if (traversal.matchesAny(element)) return true;
37	        }
38	        return false;
39	    }
40	
41	    @Override boolean wantsNodes() {
42	        return wantsNodes;
43	    }
44	
45	    @Override protected void reset() {
46	        for (Traversal traversal : traversals) traversal.evaluator.reset();
47	    }
48	
49	    @Override protected int cost() {
50	        return cost;
51	    }
52	
53	    @Override public String toString() {
54	        return ":has(" + selector + ')';
55	    }
56	
57	    /** A traversal shared by one or more {@code :has()} alternatives. */
58	    static final class Traversal {
59	        static final SoftPool<NodeIterator<Node>> NodeIterPool =
60	            new SoftPool<>(() -> new NodeIterator<>(new TextNode(""), Node.class)); // restart() replaces the placeholder root
61	
62	        final Evaluator evaluator;
63	        final Scope scope;
64	
65	        /** Creates a traversal that applies the evaluator within the given scope. */
66	        Traversal(Evaluator evaluator, Scope scope) {
67	            this.evaluator = evaluator;
68	            this.scope = scope;
69	        }
70	
71	        /** Traverses relative to the {@code :has()} subject, stopping at the first match. */
72	        boolean matchesAny(Element subject) {
73	            switch (scope) {
74	                case Children: return matchesChild(subject);
75	                case NextSibling: return matchesNextSibling(subject);
76	                case NextSiblingTree: return matchesNextSiblingTree(subject);
77	                case FollowingSiblings: return matchesSibling(subject);
78	                case FollowingSiblingTrees: return matchesFollowingSiblingTrees(subject);
79	                case Descendants: return matchesDescendants(subject);
80	                default: throw new IllegalStateException("Unknown :has() traversal scope: " + scope);
81	            }
82	        }
83	
84	        /** Tests only the subject's immediate child nodes. */
85	        private boolean matchesChild(Element subject) {
86	            for (Node child = subject.firstChild(); child != null; child = child.nextSibling()) {
87	                if (evaluator.matches(subject, child))
88	                    return true;
89	            }
90	            return false;
91	        }
92	
93	        /** Tests the subject's next element sibling for a simple {@code +} selector. */
94	        private boolean matchesNextSibling(Element subject) {
95	            Element sibling = subject.nextElementSibling();
96	            return sibling != null && evaluator.matches(subject, sibling);
97	        }
98	
99	        /** Searches the next element sibling tree, as needed by {@code :has(+ div span)}. */
100	        private boolean matchesNextSiblingTree(Element subject) {
101	            Element sibling = subject.nextElementSibling();
102	            return sibling != null && matchesNodeAndDescendants(subject, sibling);
103	        }
104	
105	        /** Tests sibling nodes after the subject, including non-element nodes when the evaluator accepts them. */
106	        private boolean matchesSibling(Element subject) {
107	            boolean nodes = evaluator.wantsNodes();
108	            for (Node sibling = nodes ? subject.nextSibling() : subject.nextElementSibling(); sibling != null;
109	                 sibling = nodes ? sibling.nextSibling() : sibling.nextElementSibling()) {
110	                if (evaluator.matches(subject, sibling))
111	                    return true;
112	            }
113	            return false;
114	        }
115	
