import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class T5 {
  static void t(Document doc, String q) {
    try { System.out.println(q + " => " + doc.select(q).size()); }
    catch (Exception e) { System.out.println(q + " => ERR " + e.getClass().getSimpleName() + ": " + e.getMessage()); }
  }
  public static void main(String[] a) {
    Document doc = Jsoup.parse(
      "<div id=a><p data-x='a,b'></p></div>" +
      "<div id=b><span title='x)y'></span></div>" +
      "<div id=c class='foo,bar'><i></i></div>" +
      "<div id=d><p>one, two</p></div>");
    t(doc, "div:has([data-x='a,b'], i)");
    t(doc, "div:has([title='x)y'])");
    t(doc, "div:has(p:contains(one, two))");
    t(doc, "div:has(.foo\\,bar)");
    t(doc, "div:has(.foo\\,bar, i)");
    t(doc, "div:has(p[data-x='a,b'], i)");
    // nested has with comma branches inside outer branches
    t(doc, "div:has(p:has([data-x='a,b'], b), i)");
    // :is with comma inside has branch, plus another outer branch
    t(doc, "div:has(:is(p, i), section)");
    // not with list
    t(doc, "div:has(:not(p, section))");
  }
}
EOF
