import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
public class T6 {
  public static void main(String[] a) {
    Document doc = Jsoup.parse("<div id=c class='foo,bar'><i></i></div>");
    for (String q : new String[]{".foo\\,bar", "div:has(.foo\\,bar)", "div:has(i.foo\\,bar)", "div:has(.foo\\,bar), div"}) {
      try { System.out.println(q + " => " + doc.select(q).size()); }
      catch (Exception e) { System.out.println(q + " => ERR " + e.getMessage()); }
    }
    // comma-containing class on the <i> directly vs descendant
    Document d2 = Jsoup.parse("<div id=c><i class='foo,bar'></i></div>");
    for (String q : new String[]{"div:has(i.foo\\,bar)", "div:has(.foo\\,bar)", "i.foo\\,bar"}) {
      System.out.println(q + " => " + d2.select(q).size());
    }
  }
}
