import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.*;
public class T7 {
  public static void main(String[] a) {
    Document doc = Jsoup.parse("<div id=a><p>hello</p><!--c--></div><div id=b><span>x</span></div>");
    // node chains in comma branches
    System.out.println(doc.select("div:has(::comment, ::text)").size()); // both divs
    System.out.println(doc.select("div:has(p ::text, ::comment)").size());
    System.out.println(doc.select("div:has(p ::text, span)").size());
    // selectNodes with has
    Nodes<Node> ns = doc.selectNodes("div:has(::comment)");
    System.out.println(ns.size());
    // ancestor/child combinators in sibling branches across documents reparse
    Document d2 = Jsoup.parse("<article id=a></article><article id=b><section><p></p></section></article>");
    System.out.println(d2.select("article:has(+ article section p)").size()); // a
    System.out.println(d2.select("article:has(+ article > section)").size()); // a
    System.out.println(d2.select("article:has(+ article p, ~ article > section)").attr("id"));
    // child-first then sibling branch where both hit same element -> once
    Document d3 = Jsoup.parse("<article id=a><p></p></article><article id=b></article>");
    Elements e = d3.select("article:has(p, + article)");
    System.out.println(e.size() + " " + e.attr("id"));
    // :has with general sibling branch and descendant continuation
    Document d4 = Jsoup.parse("<article id=a></article><h1></h1><section><p></p></section>");
    System.out.println(d4.select("article:has(~ section p)").size()); // a
    System.out.println(d4.select("article:has(~ h1 + section p)").size()); // a
    // immediate next sibling must not skip
    System.out.println(d4.select("article:has(+ section)").size()); // 0, h1 intervenes
  }
}
