      if (!doc.getElementById("a").is(combined)) throw new AssertionError("is");
      if (!doc.getElementById("a").equals(doc.getElementById("a").closest(combined))) throw new AssertionError("closest");
      if (!Jsoup.parse("<div id=a></div>").select(evaluator).isEmpty()) throw new AssertionError("empty");
    });
    System.out.println("PARALLEL OK");
  }
}
