import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.*;
public class T10 {
  static void t(Document doc, String q) {
    try { System.out.println(q + " => " + doc.select(q).size()); }
    catch (Exception e) { System.out.println(q + " => ERR " + e.getClass().getSimpleName()); }
  }
  public static void main(String[] a) {
    Document doc = Jsoup.parse("<div id=a><p></p></div><div id=b><span></span></div>");
    t(doc, "div:has(:scope)");        // self can't satisfy
    t(doc, "div:has(:scope, p)");     // = :has(p)
    t(doc, "div:has(p, :scope)");
    t(doc, "div:has(> *)");
    t(doc, "div:has(p:has(:scope))"); // inner self never matches
    t(doc, "div:has(p:has(:scope, i))");
    t(doc, "div:has(p /* c */ , span)"); // css comments?
    // newline separated
    t(doc, "div:has(p,\n span)");
    // nested has branch list
    Document d2 = Jsoup.parse("<div id=x><p><a></a></p></div><div id=y><p><b></b></p></div>");
    t(d2, "div:has(p:has(a, b))");
    // tabs and leading whitespace per branch
    t(d2, "div:has(\ta ,\nb)");
  }
}
