import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.*;
public class T14 {
  public static void main(String[] a) {
    String html = "<div id=1><section><p><b></b></p></section></div>" +
                  "<div id=2><p></p></div>" +
                  "<div id=3><section><span></span></section></div>" +
                  "<div id=4></div>";
    String q = "div:has(section:has(p b, span), p)";
    Document d = Jsoup.parse(html);
    Elements r1 = d.select(q);
    System.out.println("orig: " + r1.eachAttr("id"));
    // serialize each result element and reparse a doc containing them
    Document d2 = Jsoup.parse(r1.outerHtml());
    Elements r2 = d2.select(q);
    System.out.println("reparsed: " + r2.size());
    for (Element e : r2) System.out.println("  " + e.tagName() + " child=" + e.children().eachAttr("id") + " " + e.html().length());
    // nested hit relation preserved: inner structure
    Elements inners = d2.select("div:has(section:has(p b))");
    System.out.println("nested in reparsed: " + inners.size());
    // and the whole-doc reparse
    Document d3 = Jsoup.parse(d.html());
    System.out.println("whole reparse: " + d3.select(q).eachAttr("id"));
  }
}
